sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.student-widget {
    max-width: 500px;
    margin: 30px auto;
    padding: 25px;
    background: #ffffff;
    border-radius: 10px;
    box-shadow: 0 3px 10px rgba(0, 0, 0, 0.15);
}

.student-widget h2 {
    text-align: center;
    margin-bottom: 20px;
}

.student-widget p {
    text-align: center;
    font-size: 16px;
}

.student-widget .form-control {
    width: 100%;
    padding: 12px;
    border: 1px solid #ccc;
    border-radius: 6px;
}

.student-widget .btn-primary {
    width: 100%;
    padding: 12px;
    border: none;
    border-radius: 6px;
    background: #337ab7;
    color: white;
    cursor: pointer;
}

.student-widget .btn-primary:hover {
    background: #286090;
}
